pub(super) fn install_icons() {
    let dir = nyx_core::paths::cache_dir().join("icons");
    for (name, svg) in ICONS {
        let file = dir.join(format!("{name}.svg"));
        if std::fs::read_to_string(&file).ok().as_deref() != Some(*svg) {
            let _ = std::fs::create_dir_all(&dir);
            let _ = std::fs::write(&file, svg);
        }
    }
    if let Some(display) = gdk::Display::default() {
        gtk::IconTheme::for_display(&display).add_search_path(&dir);
    }
}

/// What the note list shows.
#[derive(Clone, PartialEq)]
pub(super) enum ListMode {
    Recent,
    Pinned,
    Daily,
    Folder(PathBuf),
    Search(String),
}

/// A row of the palette: what it runs.
type Run = Rc<dyn Fn()>;

pub(super) struct Shell {
    pub palette: gtk::Popover,
    pub palette_list: gtk::ListBox,
    pub palette_runs: RefCell<Vec<Run>>,
    /// Content matches for the palette's query, once the index answers.
    pub palette_hits: RefCell<(String, Vec<vault::SearchHit>)>,
    /// Every command, as buttons (the old ⋯ menu): the palette lists them all.
    pub commands: gtk::Box,
    pub vault_name: gtk::Label,
    pub quick: gtk::Box,
    pub tag_list: RefCell<Vec<(String, usize)>>,
    pub sync_icon: gtk::Image,
    pub sync_label: gtk::Label,
    pub list_root: gtk::Box,
    pub list_title: gtk::Label,
    pub list_count: gtk::Label,
    pub list_sort: gtk::Label,
    pub list_chips: gtk::FlowBox,
    pub list: gtk::ListBox,
    pub list_line: gtk::Separator,
    /// What the note list shows: a list chosen in the sidebar, or a search. None (a
    /// note chosen, or nothing yet) hides it; it would only repeat the tree.
    pub mode: RefCell<Option<ListMode>>,
    pub notes: RefCell<Vec<vault::Listed>>,
    pub hits: RefCell<Vec<vault::SearchHit>>,
    pub strip: gtk::Box,
    pub strip_tabs: gtk::Box,
    pub strip_pending: Cell<bool>,
    pub info_values: [gtk::Label; 4],
    pub info_captions: [gtk::Label; 4],
    pub info_props: gtk::Box,
    pub info_tags: gtk::FlowBox,
    pub info_file: gtk::Label,
    pub tasks: Cell<(usize, usize)>,
    pub format: gtk::Popover,
    pub format_parent: RefCell<Option<glib::WeakRef<gtk::Widget>>>,
    pub assist: gtk::Box,
    /// Tabs that aren't notes (Graph, History, a review), with what closes them.
    /// With what closes each, and whether the inspector stays beside it (Graph's Links).
    pub views: RefCell<Vec<(gtk::Widget, Run, bool)>>,
    /// The hidden windows behind views, with their pages.
    pub view_windows: RefCell<Vec<(glib::WeakRef<gtk::Window>, gtk::Widget)>>,
    pub welcome: Cell<bool>,
    /// Setting every note's Source, Live and Read at once.
    pub switching: Cell<bool>,
    /// A view (Graph, History…) is on show.
    pub in_view: Cell<bool>,
    /// The inspector stepped aside for lack of room (and will come back).
    pub stepped_aside: Cell<bool>,
    /// Opening or closing the inspector for room, not as the user's choice.
    pub inspector_quiet: Rc<Cell<bool>>,
}

fn label(text: &str, class: &str) -> gtk::Label {
    let l = widgets::label(text, class);
    l.set_xalign(0.0);
    l
}

fn icon_label_button(icon: &str, text: &str, class: &str) -> gtk::Button {
    let b = gtk::Button::new();
    let face = widgets::hbox(6);
    if !icon.is_empty() {
        face.append(&gtk::Image::from_icon_name(icon));
    }
    face.append(&gtk::Label::new(Some(text)));
    b.set_child(Some(&face));
    if !class.is_empty() {
        b.add_css_class(class);
    }
    b
}

/// A group heading in the sidebar (Design 2.0's: uppercase, in its section's colour,
/// `accent` for the first), with an optional + at its end.
pub(super) fn group(title: &str, section: &str, add: Option<(&str, gtk::Button)>) -> gtk::Box {
    let row = nyx_ui::sidebar::group_label(title, false);
    if let Some((tip, b)) = add {
        b.set_tooltip_text(Some(tip));
        b.add_css_class("flat");
        b.add_css_class("nav-group-add");
        b.set_valign(gtk::Align::End);
        row.append(&b);
    }
    nyx_ui::sidebar::set_section(&row, section);
    row
}

/// "Today 14:20", "Yesterday", "Mon", "10 Nov" (with the year when it isn't this one).
pub(super) fn when(seconds: i64) -> String {
    let (Ok(then), Ok(now)) = (glib::DateTime::from_unix_local(seconds), glib::DateTime::now_local()) else {
        return String::new();
    };
    let day = |d: &glib::DateTime| (d.year(), d.day_of_year());
    let fmt = |f: &str| then.format(f).map(|s| s.to_string()).unwrap_or_default();
    if day(&then) == day(&now) {
        return format!("Today {}", fmt("%H:%M"));
    }
    if now.add_days(-1).is_ok_and(|y| day(&y) == day(&then)) {
        return "Yesterday".into();
    }
    let days = (now.to_unix() - then.to_unix()) / 86_400;
    if (0..6).contains(&days) {
        return fmt("%a");
    }
    if then.year() == now.year() { fmt("%-d %b") } else { fmt("%-d %b %Y") }
}

/// A label for the palette and the list: `query`'s words in bold.
fn marked(text: &str, query: &str) -> String {
    let words: Vec<String> = query
        .split_whitespace()
        .filter(|w| !w.contains(':'))
        .map(|w| w.trim_start_matches('#').to_lowercase())
        .filter(|w| !w.is_empty())
        .collect();
    let lower = text.to_lowercase();
    let mut spans: Vec<(usize, usize)> = Vec::new();
    for w in &words {
        let mut from = 0;
        while let Some(i) = lower[from..].find(w.as_str()) {
            let a = from + i;
            spans.push((a, a + w.len()));
            from = a + w.len().max(1);
        }
    }
    spans.sort();
    let mut out = String::new();
    let mut at = 0;
    for (a, b) in spans {
        if a < at || !text.is_char_boundary(a) || !text.is_char_boundary(b) {
            continue;
        }
        out.push_str(&glib::markup_escape_text(&text[at..a]));
        out.push_str(&format!("<b>{}</b>", glib::markup_escape_text(&text[a..b])));
        at = b;
    }
    out.push_str(&glib::markup_escape_text(&text[at..]));
    out
}

/// A command's name and its key, from a menu button's label: "Save  (Ctrl+S)",
/// "Focus mode · F11".
fn split_command(text: &str) -> (String, String) {
    if let Some((name, key)) = text.split_once("  (") {
        return (name.trim().to_string(), key.trim_end_matches(')').replace('+', " "));
    }
    if let Some((name, key)) = text.split_once(" · ")
        && key.len() <= 12
    {
        return (name.trim().to_string(), key.to_string());
    }
    (text.trim().to_string(), String::new())
}

